import React, { useEffect, useState } from "react";
import MainProducts from "./MainProductsNew";
import BlogsList from "../Blogs/BlogsList";
import ShareProduct from "../ShareProduct/ShareProduct";
import { useParams, Link, useLoaderData } from "@tanstack/react-router";
import axios from "axios";
import { Swiper, SwiperSlide } from "swiper/react";
import { Autoplay } from "swiper";
import "swiper/css";
import "swiper/css/autoplay";
// import "swiper/swiper-bundle.min.css"; // Redundant with swiper/css
// import "swiper/swiper.min.css"; // Redundant with swiper/css
import Quotation from "../WhatPeopleSay/Quotation.jsx";
// AOS removed to prevent performance issues and infinite loops
import { Helmet } from "react-helmet";

const quotesImages = [
  "/static/images/QBG1.webp",
  "/static/images/QBG2.webp",
  "/static/images/QBG3.webp",
  "/static/images/QBG4.webp",
  "/static/images/QBG5.webp",
  "/static/images/QBG6.webp",
  "/static/images/QBG7.webp",
  "/static/images/QBG8.webp",
  "/static/images/QBG9.webp",
  "/static/images/QBG10.webp",
  "/static/images/QBG11.webp",
  "/static/images/QBG12.webp",
  "/static/images/QBG13.webp",
  "/static/images/QBG14.webp",
  "/static/images/QBG15.webp",
];

// SwiperCore.use([Autoplay]); // Not required in Swiper 9 if passed to modules prop

const BlogNew = () => {
  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);


  const params = useParams({ strict: false });
  let temp = params["link"] || "Hot Products";
  let temp2 = "";
  if (params["subLink"]) {
    temp2 = params["subLink"];
  }

  const selectedCat = temp;
  const subLink = temp2;

  const loaderData = useLoaderData({ strict: false }); // Generic access to loader data
  const rootData = useLoaderData({ from: '__root__' });
  const [category, setCategory] = useState(rootData?.categories || []);
  const [qoutes, setQoutes] = useState([]);
  
  const data = loaderData?.productsData;
  const products = data?.data && data.data.length > 0 && data.data[0][0] !== "" ? data.data : [];
  const metaTitle = data?.metaTitle || "";
  const loading = !loaderData;

  const metaDescription = React.useMemo(() => {
    if (data?.metaDescription) {
      const el = document.createElement("div");
      el.innerHTML = data.metaDescription;
      return el.innerText.slice(0, 170);
    }
    return "";
  }, [data?.metaDescription]);

  useEffect(() => {
    if (rootData?.categories && rootData.categories.length > 0) {
       // Only update if the reference or content actually changed
       if (JSON.stringify(rootData.categories) !== JSON.stringify(category)) {
          setCategory(rootData.categories);
       }
    } else if (category.length === 0) {
      axios.get((process.env.REACT_APP_SERVER || "").replace(/\/$/, "") + "/api/categorySideBar/")
        .then((res) => {
          if (res.data && res.data.data) {
            setCategory(res.data.data);
          }
        })
        .catch(err => console.error("Error fetching categories", err));
    }
  }, [rootData, category]);

  // useEffect removed: moved to loader

  // Fetch Quotes when category changes
  useEffect(() => {
    axios
      .get(
        (process.env.REACT_APP_SERVER || "").replace(/\/$/, "") +
          "/api/quoteList/?category=" +
          selectedCat
      )
      .then((data) => setQoutes(data["data"]["data"]))
      .catch((error) => console.log(error));
  }, [selectedCat]);

  // useEffect removed: moved to loader

  return (
    <div className="mt-16">
      <Helmet>
        <meta charSet="utf-8" />
        <title>
          {selectedCat === "Hot Products"
            ? "Material Handling Equipment Collection | Kijeka Engineers"
            : `${metaTitle} | Kijeka Engineers`}
        </title>

        <meta name="description" content={metaDescription}></meta>
        <meta property="og:type" content="website"></meta>
        <meta
          property="og:url"
          content={`https://kijeka.com/${selectedCat}${subLink ? "/" + subLink : ""}`}
        ></meta>
        <meta
          property="og:title"
          content={metaTitle || "Our Products | Kijeka Engineers"}
        ></meta>
        <meta property="og:description" content={metaDescription}></meta>
        <meta
          property="og:image"
          content="/static/images/KijekaMeta.webp"
        ></meta>
        <meta property="twitter:card" content="summary_large_image"></meta>
        <meta
          property="twitter:title"
          content={metaTitle || "Our Products | Kijeka Engineers"}
        ></meta>
        <meta property="twitter:description" content={metaDescription}></meta>
        <meta
          property="twitter:image"
          content="/static/images/KijekaMeta.webp"
        ></meta>
        <link rel="canonical" href={`https://kijeka.com/${selectedCat}${subLink ? "/" + subLink : ""}`} />
        
        {/* Structured Data for CollectionPage */}
        <script type="application/ld+json">
          {JSON.stringify({
            "@context": "https://schema.org",
            "@type": "CollectionPage",
            "name": metaTitle || "Our Products",
            "description": metaDescription,
            "url": `https://kijeka.com/${selectedCat}${subLink ? "/" + subLink : ""}`,
            "mainEntity": {
              "@type": "ItemList",
              "itemListElement": products.map((prod, idx) => ({
                "@type": "ListItem",
                "position": idx + 1,
                "url": `https://kijeka.com/product/${prod[4]}`
              }))
            }
          })}
        </script>
      </Helmet>
      <ShareProduct />
      <div className="w-full relative">
        <div className="text-white">
          <Swiper
            grabCursor={true}
            centeredSlides={true}
            slidesPerView={1}
            autoplay={{
              delay: 3000,
              disableOnInteraction: false,
            }}
            modules={[Autoplay]}
            loop={true}
            className="mySwiper h-fit w-full flex justify-between items-center"
          >
            {qoutes.map((item, index) => (
              <SwiperSlide
                className="w-full lg:p-12 p-4 lg:min-h-[200px] min-h-[150px] items-center justify-center"
                key={index}
                style={{
                  backgroundImage:
                    "linear-gradient(180deg, rgba(0, 21, 75, 0.5) 0%, rgba(0, 21, 75, 0) 237.41%), url(" +
                    quotesImages[index % 15] +
                    ")",
                  backgroundSize: "cover",
                  backgroundRepeat: "no-repeat",
                  display: "flex",
                }}
              >
                <div className="flex items-center justify-center">
                  <p className="lg:text-xl md:text-base text-xs text-justify lg:mt-2 md:text-center lg:ml-5 relative">
                    <Quotation className="w-10 h-10 -translate-y-5" />
                    &nbsp;{item}
                  </p>
                </div>
              </SwiperSlide>
            ))}
          </Swiper>
        </div>
      </div>
      <div className="">
        <div className="box h-[5rem] w-fit pl-10 relative flex justify-start items-start ml-[2rem] max-sm:ml-0 group mt-5">
          <div className="h-12 w-1.5 bg-[#004B95] absolute mr-[1rem] origin-left group-hover:w-full duration-300 group"></div>
          <h1 className="text-[24px] font-bold text-[#004B95] mt-[0.5rem] ml-[1rem] group-hover:text-white group-hover:translate-x-5 duration-300 capitalize">
            {selectedCat !== ""
              ? selectedCat.replace(/-/g, " ")
              : "Hot Products"}
          </h1>
        </div>
      </div>

      <div className="sm:flex sm:flex-row sm:gap-5 sm:mb-5 sm:mx-5 flex flex-col">
        <div className="sm:w-[30%] w-full sm:ml-[1%] mx-auto px-6">
          <BlogsList listdData={category} />
        </div>
        <div className="sm:w-[80%] mt-5 md:mt-0 px-4">
          <div className="">
            <div className="">
              {category.map((item, index) => {
                if (item[1] === selectedCat) {
                  return (
                    <div key={index} className="px-2">
                      {item[2].length !== 0 ? (
                        <div
                          id="subCategory"
                          className="border-[1px] rounded-lg lg:w-[100%] border-kijeka-blue mb-5"
                        >
                          <div className="overflow-hidden text-kijeka-blue">
                            <ul className="text-sm text-kijeka-blue flex items-center mnd:justify-center gap-x-5 flex-wrap py-2 md:px-10 px-5">
                              {item[2].map((subItem, subIndex) => {
                                return subLink === subItem[1] ? (
                                      <li
                                        key={subIndex}
                                        className="border-b-2 border-kijeka-blue bg-kijeka-blue text-white p-2 rounded-md"
                                      >
                                        <Link to={`/${item[1]}/${subItem[1]}`} preload="intent">
                                          {subItem[0]}
                                        </Link>
                                      </li>
                                    ) : (
                                      <li key={subIndex} className="p-2">
                                        <Link to={`/${item[1]}/${subItem[1]}`} preload="intent">
                                          {subItem[0]}
                                        </Link>
                                      </li>
                                );
                              })}
                            </ul>
                          </div>
                        </div>
                      ) : null}
                    </div>
                  );
                }
                return null;
              })}
            </div>
          </div>
          <MainProducts product={products} loading={loading} />
        </div>
      </div>
    </div>
  );
};

export default BlogNew;
